//! Rust port of tests/test7.cpp (Clipper2 black-box reimplementation).
//!
//! Mirrors the C++ program: intersect a square with a triangle, inflate the
//! result by a CLI-supplied offset (Round joins), print the area of the first
//! resulting path (or 0 if empty).

mod clip;
mod fmt;
mod geom;
mod offset;

use geom::{EndType, FillRule, JoinType, Path64, Paths64, Point64};

/// Mimics std::stoi: skips leading whitespace, optional sign, parses digits
/// until the first non-digit. Aborts like an uncaught C++ exception when no
/// digits are present or the value is out of `int` range.
fn parse_stoi(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val * 10 + (bytes[i] - b'0') as i64;
        i += 1;
    }
    if i == start {
        eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
        eprintln!("  what():  stoi");
        std::process::abort();
    }
    let val = sign * val;
    if val < i32::MIN as i64 || val > i32::MAX as i64 {
        eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
        eprintln!("  what():  stoi");
        std::process::abort();
    }
    val
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let offset: i64 = if args.len() > 1 { parse_stoi(&args[1]) } else { 10 };

    let square: Path64 = vec![
        Point64::new(0, 0),
        Point64::new(100, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ];
    let triangle: Path64 = vec![
        Point64::new(50, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ];

    let subjects: Paths64 = vec![square];
    let clips: Paths64 = vec![triangle];

    let intersected = clip::intersect(&subjects, &clips, FillRule::EvenOdd);
    let offset_result = offset::inflate_paths(
        &intersected,
        offset as f64,
        JoinType::Round,
        EndType::Polygon,
    );

    if !offset_result.is_empty() && !offset_result[0].is_empty() {
        let a = geom::area(&offset_result[0]);
        let bounds = geom::get_bounds(&offset_result);
        let _width = bounds.right - bounds.left;
        let _height = bounds.bottom - bounds.top;
        println!("{}", fmt::format_cpp_f64(a));
    } else {
        println!("0");
    }
}

