//! Polygon clipping (boolean intersection), mirroring Clipper2Lib::Intersect.
//!
//! IMPLEMENTATION CONTRACT (fixed — the crate root calls this exact signature):
//!   pub fn intersect(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64
//!
//! Implementation notes:
//! This is a simplified black-box reimplementation for the test7 workload.
//! Each subject path is clipped against each clip path independently using
//! the Sutherland–Hodgman algorithm (valid because the clip polygons in this
//! workload are convex). Non-empty results (>= 3 vertices) are collected.
//! Subject vertex order/orientation is preserved. The `fill_rule` parameter is
//! accepted for API fidelity; for these simple non-self-intersecting inputs
//! all fill rules give identical results.

use crate::geom::{area, FillRule, Path64, Paths64, Point64};

/// 2D cross product of vectors (b - a) x (p - a), in f64 to avoid overflow.
fn cross(a: Point64, b: Point64, p: Point64) -> f64 {
    (b.x - a.x) as f64 * (p.y - a.y) as f64 - (b.y - a.y) as f64 * (p.x - a.x) as f64
}

/// Is `p` inside (or on) the half-plane defined by clip edge `a -> b`?
/// `sign` is the orientation of the clip polygon (+1.0 for CCW, -1.0 for CW).
fn inside(a: Point64, b: Point64, p: Point64, sign: f64) -> bool {
    cross(a, b, p) * sign >= 0.0
}

/// Intersection point of segment `s -> e` with the infinite line through
/// clip edge `a -> b`, rounded to the nearest integer coordinates.
fn line_intersection(s: Point64, e: Point64, a: Point64, b: Point64) -> Point64 {
    let d1 = cross(a, b, s);
    let d2 = cross(a, b, e);
    // Parametric position along s -> e where the signed distance is zero.
    let t = d1 / (d1 - d2);
    let x = s.x as f64 + t * (e.x - s.x) as f64;
    let y = s.y as f64 + t * (e.y - s.y) as f64;
    Point64 {
        x: x.round() as i64,
        y: y.round() as i64,
    }
}

/// Sutherland–Hodgman: clip subject polygon `subject` against the convex
/// clip polygon `clip`. Returns the (possibly empty) clipped polygon.
fn clip_convex(subject: &Path64, clip: &Path64) -> Path64 {
    let mut output = subject.clone();
    let m = clip.len();
    if m < 3 {
        return Path64::new();
    }
    // Orientation of the clip polygon determines which side is "inside".
    let sign = if area(clip) >= 0.0 { 1.0 } else { -1.0 };
    for i in 0..m {
        let a = clip[i];
        let b = clip[(i + 1) % m];
        let input = output;
        output = Path64::new();
        let n = input.len();
        if n == 0 {
            break;
        }
        let mut s = input[n - 1];
        let mut s_inside = inside(a, b, s, sign);
        for &e in &input {
            let e_inside = inside(a, b, e, sign);
            if e_inside {
                if !s_inside {
                    output.push(line_intersection(s, e, a, b));
                }
                output.push(e);
            } else if s_inside {
                output.push(line_intersection(s, e, a, b));
            }
            s = e;
            s_inside = e_inside;
        }
    }
    output
}

pub fn intersect(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut result = Paths64::new();
    for subject in subjects {
        if subject.len() < 3 {
            continue;
        }
        for clip in clips {
            let clipped = clip_convex(subject, clip);
            if clipped.len() >= 3 && area(&clipped) != 0.0 {
                result.push(clipped);
            }
        }
    }
    result
}

