#[path = "/output/geom.rs"]
mod geom;
#[path = "/output/clip.rs"]
mod clip;

use geom::*;

fn p(x: i64, y: i64) -> Point64 {
    Point64::new(x, y)
}

fn main() {
    let mut failures = 0;

    // Case 1: the actual workload — square subject, triangle clip inside it.
    let square: Path64 = vec![p(0, 0), p(100, 0), p(100, 100), p(0, 100)];
    let triangle: Path64 = vec![p(50, 0), p(100, 100), p(0, 100)];
    let r = intersect(&vec![square.clone()], &vec![triangle.clone()], FillRule::EvenOdd);
    println!("case1: {} path(s)", r.len());
    assert_eq!(r.len(), 1, "expected exactly one result path");
    let a = area(&r[0]);
    println!("case1: area = {} (expected 5000)", a);
    if a != 5000.0 {
        failures += 1;
    }
    if r[0].len() != 3 {
        failures += 1;
        println!("case1: FAIL vertex count {} != 3: {:?}", r[0].len(), r[0]);
    } else {
        // Must contain exactly the 3 triangle vertices (same winding order).
        let expect = &triangle;
        let n = r[0].len();
        let ok = (0..n).any(|k| (0..n).all(|i| r[0][(k + i) % n] == expect[i]));
        if !ok {
            failures += 1;
            println!("case1: FAIL vertices {:?} != {:?}", r[0], expect);
        } else {
            println!("case1: vertices match triangle exactly (orientation preserved)");
        }
    }

    // Case 2: partially overlapping convex polygons.
    // Subject: square (0,0),(100,0),(100,100),(0,100)
    // Clip:    square (50,50),(150,50),(150,150),(50,150)
    // Overlap: square (50,50)..(100,100) => area 2500, 4 vertices.
    let clip2: Path64 = vec![p(50, 50), p(150, 50), p(150, 150), p(50, 150)];
    let r2 = intersect(&vec![square.clone()], &vec![clip2], FillRule::NonZero);
    let a2 = if r2.is_empty() { 0.0 } else { area(&r2[0]) };
    println!(
        "case2: {} path(s), area = {} (expected 2500), verts = {:?}",
        r2.len(),
        a2,
        r2.get(0)
    );
    if r2.len() != 1 || a2 != 2500.0 || r2[0].len() != 4 {
        failures += 1;
    }
    let expect2 = [p(50, 50), p(100, 50), p(100, 100), p(50, 100)];
    let n2 = r2[0].len();
    if !(0..n2).any(|k| (0..n2).all(|i| r2[0][(k + i) % n2] == expect2[i])) {
        failures += 1;
        println!("case2: FAIL vertex set mismatch");
    }

    // Case 3: disjoint polygons => empty result.
    let far: Path64 = vec![p(200, 200), p(300, 200), p(300, 300), p(200, 300)];
    let r3 = intersect(&vec![square.clone()], &vec![far], FillRule::EvenOdd);
    println!("case3: {} path(s) (expected 0)", r3.len());
    if !r3.is_empty() {
        failures += 1;
    }

    // Case 4: intersection points at non-integer spots that round cleanly.
    // Subject: square (0,0),(100,0),(100,100),(0,100)
    // Clip:    triangle (0,0),(100,0),(0,100) — diagonal cut of the square.
    // Expected: triangle (0,0),(100,0),(0,100) area 5000.
    let half: Path64 = vec![p(0, 0), p(100, 0), p(0, 100)];
    let r4 = intersect(&vec![square.clone()], &vec![half.clone()], FillRule::EvenOdd);
    let a4 = if r4.is_empty() { 0.0 } else { area(&r4[0]) };
    println!("case4: {} path(s), area = {} (expected 5000)", r4.len(), a4);
    if r4.len() != 1 || a4 != 5000.0 {
        failures += 1;
    }

    if failures == 0 {
        println!("ALL TESTS PASSED");
    } else {
        println!("{} FAILURE(S)", failures);
        std::process::exit(1);
    }
}

