//! C++ iostream default double formatting (`std::cout << value`, precision 6,
//! default float format == printf "%g" semantics).
//!
//! IMPLEMENTATION CONTRACT (fixed — the crate root calls this exact signature):
//!   pub fn format_cpp_f64(v: f64) -> String

/// Format a double exactly like C++ `std::cout << v` with default settings,
/// i.e. printf("%g", v): 6 significant digits, round-half-to-even, scientific
/// notation when the (post-rounding) decimal exponent is < -4 or >= 6,
/// otherwise fixed notation with trailing fractional zeros stripped.
pub fn format_cpp_f64(v: f64) -> String {
    if v.is_nan() {
        return "nan".to_string();
    }
    if v.is_infinite() {
        return if v > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }

    // "{:.5e}" yields "[-]d.ddddde[-]X" with correctly rounded
    // (round-half-to-even) 6 significant digits.
    let s = format!("{:.5e}", v);
    let (mantissa, exp_str) = s.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();

    let (sign, mantissa) = match mantissa.strip_prefix('-') {
        Some(rest) => ("-", rest),
        None => ("", mantissa),
    };
    // mantissa is "d.ddddd"; collect the 6 significant digits.
    let digits: Vec<u8> = mantissa.bytes().filter(|b| b.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    if !(-4..6).contains(&exp) {
        // Scientific notation: strip trailing zeros from the mantissa fraction.
        let mut frac: &[u8] = &digits[1..];
        while let Some((&b'0', rest)) = frac.split_last() {
            frac = rest;
        }
        let mut out = String::new();
        out.push_str(sign);
        out.push(digits[0] as char);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(std::str::from_utf8(frac).unwrap());
        }
        out.push('e');
        if exp < 0 {
            out.push('-');
        } else {
            out.push('+');
        }
        let abs_exp = exp.unsigned_abs();
        if abs_exp < 10 {
            out.push('0');
        }
        out.push_str(&abs_exp.to_string());
