// Fitting harness: sweep raw-offset generation variants against positive-delta probes.
use std::f64::consts::PI;

#[derive(Clone, Copy, Debug)]
struct P {
    x: f64,
    y: f64,
}

fn unit_normal(ax: i64, ay: i64, bx: i64, by: i64) -> P {
    let dx = (bx - ax) as f64;
    let dy = (by - ay) as f64;
    if dx == 0.0 && dy == 0.0 {
        return P { x: 0.0, y: 0.0 };
    }
    let f = 1.0 / dx.hypot(dy);
    P { x: dy * f, y: -dx * f }
}

#[derive(Clone, Copy, PartialEq)]
enum RM {
    Even,
    Away,
}
fn rnd(v: f64, rm: RM) -> i64 {
    match rm {
        RM::Even => v.round_ties_even() as i64,
        RM::Away => v.round() as i64,
    }
}

#[derive(Clone, Copy, PartialEq)]
enum AM {
    Atan2,   // angle between normals
    Interior, // PI - that
}

#[derive(Clone, Copy, PartialEq)]
enum VM {
    A, // push rot^1..rot^N
    B, // push n1, rot^1..rot^(N-1)
    C, // push n1, rot^1..rot^(N-1), n2
}

fn steps_for(d: f64, angle: f64, sf: usize) -> usize {
    let ad = d.abs();
    let arc_tol = 0.25 * (2.0 + ad).log10();
    let sp360 = match sf / 3 {
        0 => PI / (1.0 - arc_tol / ad).acos(),
        1 => (ad * PI).min(PI / (1.0 - arc_tol / ad).acos()),
        2 => PI / (1.0 - arc_tol.min(ad) / ad).acos(),
        _ => unreachable!(),
    };
    let raw = sp360 * angle.abs() / (2.0 * PI);
    match sf % 3 {
        0 => raw.ceil() as usize,
        1 => raw.floor() as usize,
        2 => raw.round() as usize,
    }
}

fn gen(delta: f64, rm: RM, am: AM, sf: usize, vm: VM) -> Vec<(i64, i64)> {
    let tri = [(50i64, 0i64), (100, 100), (0, 100)];
    let n = tri.len();
    let mut normals = Vec::new();
    for i in 0..n {
        let (ax, ay) = tri[i];
        let (bx, by) = tri[(i + 1) % n];
        normals.push(unit_normal(ax, ay, bx, by));
    }
    let mut out: Vec<(i64, i64)> = Vec::new();
    let mut k = n - 1;
    for j in 0..n {
        let (px, py) = tri[j];
        let sin_a = (normals[k].x * normals[j].y - normals[k].y * normals[j].x).clamp(-1.0, 1.0);
        let cos_a = normals[j].x * normals[k].x + normals[j].y * normals[k].y;
        if sin_a * delta < 0.0 {
            // concave: A, vertex, B
            for nn in [normals[k], normals[j]] {
                out.push((
                    rnd(px as f64 + nn.x * delta, rm),
                    rnd(py as f64 + nn.y * delta, rm),
                ));
                if nn.x == normals[k].x && nn.y == normals[k].y {
                    out.push((px, py));
                }
            }
        } else {
            let a2 = sin_a.atan2(cos_a);
            let angle = match am {
                AM::Atan2 => a2,
                AM::Interior => PI - a2,
            };
            let steps = steps_for(delta, angle, sf).max(1);
            // rotation step uses the *true* angle between normals
            let step = a2 / steps as f64;
            let sn = step.sin();
            let cs = step.cos();
            let n1 = normals[k];
            let n2 = normals[j];
            let push = |v: P, out: &mut Vec<(i64, i64)>| {
                out.push((
                    rnd(px as f64 + v.x * delta, rm),
                    rnd(py as f64 + v.y * delta, rm),
                ));
            };
            match vm {
                VM::A => {
                    let mut v = n1;
                    for _ in 0..steps {
                        v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
                        push(v, &mut out);
                    }
                }
                VM::B => {
                    push(n1, &mut out);
                    let mut v = n1;
                    for _ in 1..steps {
                        v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
                        push(v, &mut out);
                    }
                }
                VM::C => {
                    push(n1, &mut out);
                    let mut v = n1;
                    for _ in 1..steps {
                        v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
                        push(v, &mut out);
                    }
                    push(n2, &mut out);
                }
            }
        }
        k = j;
    }
    out
}

fn area2(pts: &[(i64, i64)]) -> i64 {
    let n = pts.len();
    let mut s: i128 = 0;
    for i in 0..n {
        let (x1, y1) = pts[i];
        let (x2, y2) = pts[(i + 1) % n];
        s += x1 as i128 * y2 as i128 - x2 as i128 * y1 as i128;
    }
    (s / 2) as i64 * 2 + (s % 2) as i64 // keep parity
}

fn main() {
    // positive probes only (raw contour should be simple -> no union needed)
    let table = std::fs::read_to_string("/tmp/probe.txt").unwrap();
    let mut probes: Vec<(i64, f64, f64)> = Vec::new(); // delta, expected, tol
    for line in table.lines() {
        let mut it = line.split_whitespace();
        let d: i64 = it.next().unwrap().parse().unwrap();
        let es = it.next().unwrap();
        let e: f64 = es.parse().unwrap();
        // tolerance: %g rounding for e-notation rows
        let tol = if es.contains('e') {
            let mant = es.split('e').next().unwrap().replace(['.', '-'], "");
            let sig = mant.len() as i32;
            let exp: i32 = es.split('e').nth(1).unwrap().parse().unwrap();
            0.5 * 10f64.powi(exp - sig + 1)
        } else {
            1e-9
        };
        if d > 0 {
            probes.push((d, e, tol));
        }
    }
    let rms = [RM::Even, RM::Away];
    let ams = [AM::Atan2, AM::Interior];
    let vms = [VM::A, VM::B, VM::C];
    let mut winners = Vec::new();
    for rm in rms {
        for am in ams {
            for sf in 0..9 {
                for vm in vms {
                    let mut ok = true;
                    let mut first_bad = String::new();
                    for (d, e, tol) in &probes {
                        let pts = gen(*d as f64, rm, am, sf, vm);
                        let a = area2(&pts) as f64 / 2.0 * 2.0; // noop
                        let s: i128 = {
                            let n = pts.len();
                            let mut s: i128 = 0;
                            for i in 0..n {
                                s += pts[i].0 as i128 * pts[(i + 1) % n].1 as i128
                                    - pts[(i + 1) % n].0 as i128 * pts[i].1 as i128;
                            }
                            s
                        };
                        let area = s as f64 / 2.0;
                        let _ = a;
                        if (area - e).abs() > *tol {
                            ok = false;
                            first_bad = format!("d={} got {} want {}", d, area, e);
                            break;
                        }
                    }
                    if ok {
                        winners.push(format!("rm={:?} am={:?} sf={} vm={:?}", rm, am, sf, vm));
                    } else if sf <= 2 && vm == VM::C {
                        println!(
                            "rm={:?} am={:?} sf={} vm={:?}: {}",
                            rm, am, sf, vm, first_bad
                        );
                    }
                }
            }
        }
    }
    println!("=== WINNERS (match all positive probes) ===");
    for w in &winners {
        println!("{}", w);
    }
    if winners.is_empty() {
        println!("none");
    }
}

