// For each positive delta, find (N0, N1) arc step counts that reproduce the oracle area.
// Corners: v0 has angle A0 = 2.2142974..., v1/v2 have A1 = 2.0344439...
use std::f64::consts::PI;

#[derive(Clone, Copy)]
struct P {
    x: f64,
    y: f64,
}

fn unit_normal(ax: i64, ay: i64, bx: i64, by: i64) -> P {
    let dx = (bx - ax) as f64;
    let dy = (by - ay) as f64;
    let f = 1.0 / dx.hypot(dy);
    P { x: dy * f, y: -dx * f }
}

fn ties_even(v: f64) -> i64 {
    let f = v.floor();
    let frac = v - f;
    if frac < 0.5 {
        f as i64
    } else if frac > 0.5 {
        f as i64 + 1
    } else {
        let fi = f as i64;
        if fi % 2 == 0 {
            fi
        } else {
            fi + 1
        }
    }
}

fn arc_pts(px: i64, py: i64, n1: P, n2: P, a2: f64, steps: usize, delta: f64, even: bool, vm: char, out: &mut Vec<(i64, i64)>) {
    let r = |v: f64| if even { ties_even(v) } else { v.round() as i64 };
    let push = |v: P, out: &mut Vec<(i64, i64)>| {
        out.push((r(px as f64 + v.x * delta), r(py as f64 + v.y * delta)));
    };
    let step = a2 / steps as f64;
    let sn = step.sin();
    let cs = step.cos();
    match vm {
        'a' => {
            let mut v = n1;
            for _ in 0..steps {
                v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
                push(v, out);
            }
        }
        'b' => {
            push(n1, out);
            let mut v = n1;
            for _ in 1..steps {
                v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
                push(v, out);
            }
        }
        _ => {
            push(n1, out);
            let mut v = n1;
            for _ in 1..steps {
                v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
                push(v, out);
            }
            push(n2, out);
        }
    }
}

fn area(pts: &[(i64, i64)]) -> f64 {
    let n = pts.len();
    let mut s: i128 = 0;
    for i in 0..n {
        s += pts[i].0 as i128 * pts[(i + 1) % n].1 as i128
            - pts[(i + 1) % n].0 as i128 * pts[i].1 as i128;
    }
    s as f64 / 2.0
}

fn main() {
    let tri = [(50i64, 0i64), (100, 100), (0, 100)];
    let normals: Vec<P> = (0..3)
        .map(|i| {
            let (ax, ay) = tri[i];
            let (bx, by) = tri[(i + 1) % 3];
            unit_normal(ax, ay, bx, by)
        })
        .collect();
    // angles between normals at v0, v1 (=v2)
    let angle = |k: usize, j: usize| -> f64 {
        let sin_a = (normals[k].x * normals[j].y - normals[k].y * normals[j].x).clamp(-1.0, 1.0);
        let cos_a = normals[j].x * normals[k].x + normals[j].y * normals[k].y;
        sin_a.atan2(cos_a)
    };
    let a0 = angle(2, 0);
    let a1 = angle(0, 1);
    println!("A0 = {:.10}, A1 = {:.10}", a0, a1);

    let table = std::fs::read_to_string("/tmp/probe.txt").unwrap();
    for line in table.lines() {
        let mut it = line.split_whitespace();
        let d: i64 = it.next().unwrap().parse().unwrap();
        let es = it.next().unwrap();
        let e: f64 = es.parse().unwrap();
        if d <= 0 {
            continue;
        }
        let tol = if es.contains('e') {
            let mant = es.split('e').next().unwrap().replace(['.', '-'], "");
            let sig = mant.len() as i32;
            let exp: i32 = es.split('e').nth(1).unwrap().parse().unwrap();
            0.5 * 10f64.powi(exp - sig + 1)
        } else {
            1e-9
        };
        let mut matches: Vec<(usize, usize, char, bool)> = Vec::new();
        for vm in ['c', 'b', 'a'] {
            for even in [true, false] {
                for n0 in 1..=120usize {
                    for n1 in 1..=120usize {
                        let mut out: Vec<(i64, i64)> = Vec::new();
                        arc_pts(50, 0, normals[2], normals[0], a0, n0, d as f64, even, vm, &mut out);
                        arc_pts(100, 100, normals[0], normals[1], a1, n1, d as f64, even, vm, &mut out);
                        arc_pts(0, 100, normals[1], normals[2], a1, n1, d as f64, even, vm, &mut out);
                        let ar = area(&out);
                        if (ar - e).abs() <= tol {
                            matches.push((n0, n1, vm, even));
                        }
                    }
                }
            }
        }
        // summarize: distinct (n0,n1) with variant/rounding flags
        let mut seen: Vec<String> = Vec::new();
        for (n0, n1, vm, even) in &matches {
            seen.push(format!("{}/{}/{}{}", n0, n1, vm, if *even { "e" } else { "a" }));
        }
        println!("d={}: want {} -> {}", d, e, if seen.is_empty() { "NO MATCH".to_string() } else { seen.join(" ") });
    }
}

