    let sn = step.sin();
    let cs = step.cos();
    let rad_mid = delta / (step / 2.0).cos();
    let rad_end = if rmodel == 2 { rad_mid } else { delta };
    let mut push = |v: P, rad: f64| {
        out.push((r(px as f64 + v.x * rad), r(py as f64 + v.y * rad)));
    };
    // variant C: push n1, rot^1..rot^(N-1), n2
    push(n1, rad_end);
    let mut v = n1;
    for _ in 1..steps {
        v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
        push(v, if rmodel == 0 { delta } else { rad_mid });
    }
    push(n2, rad_end);
}

fn area(pts: &[(i64, i64)]) -> f64 {
    let n = pts.len();
    let mut s: i128 = 0;
    for i in 0..n {
        s += pts[i].0 as i128 * pts[(i + 1) % n].1 as i128
            - pts[(i + 1) % n].0 as i128 * pts[i].1 as i128;
    }
    s as f64 / 2.0
}

fn main() {
    let tri = [(50i64, 0i64), (100, 100), (0, 100)];
    let normals: Vec<P> = (0..3)
        .map(|i| {
            let (ax, ay) = tri[i];
            let (bx, by) = tri[(i + 1) % 3];
            unit_normal(ax, ay, bx, by)
        })
        .collect();
    let angle = |k: usize, j: usize| -> f64 {
        let sin_a = (normals[k].x * normals[j].y - normals[k].y * normals[j].x).clamp(-1.0, 1.0);
        let cos_a = normals[j].x * normals[k].x + normals[j].y * normals[k].y;
        sin_a.atan2(cos_a)
    };
    let a0 = angle(2, 0);
    let a1 = angle(0, 1);

    let table = std::fs::read_to_string("/tmp/probe.txt").unwrap();
    for line in table.lines() {
        let mut it = line.split_whitespace();
        let d: i64 = it.next().unwrap().parse().unwrap();
        let es = it.next().unwrap();
        let e: f64 = es.parse().unwrap();
        if d <= 0 {
            continue;
        }
        let tol = if es.contains('e') {
            let mant = es.split('e').next().unwrap().replace(['.', '-'], "");
            let sig = mant.len() as i32;
            let exp: i32 = es.split('e').nth(1).unwrap().parse().unwrap();
            0.5 * 10f64.powi(exp - sig + 1)
        } else {
            1e-9
        };
        let mut matches: Vec<String> = Vec::new();
        for rmodel in 0..=2usize {
            for even in [true, false] {
                for n0 in 1..=80usize {
                    for n1 in 1..=80usize {
                        let mut out: Vec<(i64, i64)> = Vec::new();
                        arc_pts(50, 0, normals[2], normals[0], a0, n0, d as f64, even, rmodel, &mut out);
                        arc_pts(100, 100, normals[0], normals[1], a1, n1, d as f64, even, rmodel, &mut out);
                        arc_pts(0, 100, normals[1], normals[2], a1, n1, d as f64, even, rmodel, &mut out);
                        let ar = area(&out);
                        if (ar - e).abs() <= tol {
                            matches.push(format!(
                                "{}/{}r{}{}",
                                n0,
                                n1,
                                rmodel,
                                if even { "e" } else { "a" }
                            ));
                        }
                    }
                }
            }
        }
        // compress: report only minimal N pairs (n0 <= 40, n1 <= 40) to keep output small
        let small: Vec<&String> = matches.iter().take(400).collect();
        println!(
            "d={}: want {} -> {}",
            d,
            e,
            if small.is_empty() {
                "NO MATCH".to_string()
            } else {
                small
                    .iter()
                    .map(|s| s.as_str())
                    .collect::<Vec<_>>()
                    .join(" ")
            }
        );
    }
}

